# Sending Welcome Emails to a List of Users

Here's a robust implementation that handles both synchronous and asynchronous `sendEmail` functions, isolates failures so one bad email doesn't stop the rest, and reports results.

```javascript
/**
 * Sends a welcome email to each user in the list.
 *
 * @param {Array<Object>} users - List of user objects.
 * @param {Function} sendEmail - Function that sends an email to a user.
 *                               May be sync or return a Promise.
 * @param {Object} [options]
 * @param {number} [options.concurrency=5] - Max emails sent in parallel.
 * @returns {Promise<{ sent: Object[], failed: { user: Object, error: Error }[] }>}
 */
async function sendWelcomeEmails(users, sendEmail, { concurrency = 5 } = {}) {
  if (!Array.isArray(users)) {
    throw new TypeError("users must be an array");
  }
  if (typeof sendEmail !== "function") {
    throw new TypeError("sendEmail must be a function");
  }
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError("concurrency must be a positive integer");
  }

  const sent = [];
  const failed = [];
  let index = 0;

  // Each worker pulls the next user from the shared queue until it's empty.
  async function worker() {
    while (index < users.length) {
      const user = users[index++];

      if (!user) {
        failed.push({ user, error: new Error("Invalid user entry") });
        continue;
      }

      try {
        await sendEmail(user); // works whether sendEmail is sync or async
        sent.push(user);
      } catch (error) {
        failed.push({ user, error });
      }
    }
  }

  const workerCount = Math.min(concurrency, users.length);
  await Promise.all(Array.from({ length: workerCount }, worker));

  return { sent, failed };
}
```

## Example Usage

```javascript
// Mock sendEmail that simulates network delay and occasional failure
async function sendEmail(user) {
  await new Promise((resolve) => setTimeout(resolve, 100));
  if (!user.email) {
    throw new Error(`User ${user.name} has no email address`);
  }
  console.log(`Welcome email sent to ${user.email}`);
}

const users = [
  { name: "Alice", email: "alice@example.com" },
  { name: "Bob", email: "bob@example.com" },
  { name: "Carol" }, // missing email -> will fail
  { name: "Dave", email: "dave@example.com" },
];

sendWelcomeEmails(users, sendEmail, { concurrency: 2 }).then(({ sent, failed }) => {
  console.log(`\nSent: ${sent.length}, Failed: ${failed.length}`);
  failed.forEach(({ user, error }) =>
    console.error(`  - ${user?.name ?? "unknown"}: ${error.message}`)
  );
});
```

**Output:**
```
Welcome email sent to alice@example.com
Welcome email sent to bob@example.com
Welcome email sent to dave@example.com

Sent: 3, Failed: 1
  - Carol: User Carol has no email address
```

## Key Design Decisions

| Feature | Why it matters |
|---|---|
| **Per-user `try/catch`** | One failed email doesn't abort the whole batch. |
| **`await` on every call** | Works with both sync and Promise-returning `sendEmail`. |
| **Concurrency limit** | Avoids overwhelming the mail server or hitting rate limits, while being faster than strictly sequential sending. |
| **Returns `{ sent, failed }`** | The caller can log, retry, or alert on failures. |
| **Input validation** | Fails fast on programming errors (wrong argument types). |

