```javascript
/**
 * Sends a welcome email to each user in a list.
 *
 * @param {Array<Object>} users - List of user objects (e.g. { name, email }).
 * @param {(user: Object) => Promise<any>|any} sendEmail - Provided send function.
 * @returns {Promise<{ sent: Object[], failed: { user: Object, error: Error }[] }>}
 */
async function sendWelcomeEmails(users, sendEmail) {
  if (!Array.isArray(users)) {
    throw new TypeError("users must be an array");
  }
  if (typeof sendEmail !== "function") {
    throw new TypeError("sendEmail must be a function");
  }

  const results = await Promise.allSettled(
    users.map(async (user) => {
      await sendEmail(user);
      return user;
    })
  );

  const sent = [];
  const failed = [];

  results.forEach((result, i) => {
    if (result.status === "fulfilled") {
      sent.push(users[i]);
    } else {
      failed.push({ user: users[i], error: result.reason });
    }
  });

  return { sent, failed };
}
```

**Usage:**

```javascript
