  console.log(`Sending welcome email to ${user.email}`);
  // ...actual sending logic
}

sendWelcomeEmails(users, sendEmail).then(({ sent, failed }) => {
  console.log(`Sent: ${sent.length}, Failed: ${failed.length}`);
});
```

**Notes:**

- **`Promise.allSettled`** ensures one failed email doesn't stop the others, and you get a report of successes and failures.
