```javascript
/**
 * Sends a welcome email to each user in a list.
 *
 * @param {Array<Object>} users - List of user objects (e.g. { name, email }).
 * @param {(user: Object) => Promise<any>|any} sendEmail - Provided send function.
 * @param {Object} [options]
 * @param {number} [options.concurrency=5] - Max emails sent simultaneously.
 * @returns {Promise<{sent: Array<Object>, failed: Array<{user: Object, error: Error}>}>}
 */
async function sendWelcomeEmails(users, sendEmail, { concurrency = 5 } = {}) {
  if (!Array.isArray(users)) {
    throw new TypeError("users must be an array");
  }
  if (typeof sendEmail !== "function") {
    throw new TypeError("sendEmail must be a function");
  }

  const sent = [];
  const failed = [];
  let index = 0;

  async function worker() {
    while (index < users.length) {
      const user = users[index++];
      try {
        await sendEmail(user);
        sent.push(user);
      } catch (error) {
        failed.push({ user, error });
      }
    }
  }

  const workerCount = Math.min(Math.max(1, concurrency), users.length);
  await Promise.all(Array.from({ length: workerCount }, worker));

  return { sent, failed };
}
