 * Adds each product in an array to a cart Map.
 * If a product is already in the cart, its quantity is increased.
 *
 * @param {Map<string|number, {product: object, quantity: number}>} cart
 * @param {Array<{id: string|number, name?: string, price?: number}>} products
 * @returns {Map} the updated cart
 */
function addProductsToCart(cart, products) {
