function warnUnknownConfigKeys(config, allowedKeys) {
  const allowed = new Set(allowedKeys);

  for (const key of Object.keys(config)) {
    if (!allowed.has(key)) {
      console.warn(`Unknown config key: "${key}"`);
    }
  }
}

// Example usage:
