  host: "localhost",
  port: 3000,
  debug: true,
  timeout: 5000
};

warnUnknownConfigKeys(config, ["host", "port", "timeout"]);
// Warning: Unknown config key: "debug"
```

`Object.keys()` checks the config’s own enumerable keys, and the `Set` makes allowed-key lookups efficient.

