## Enhanced version

If you want more helpful warnings (like typo suggestions) and support for nested objects:

```javascript
function warnUnknownKeys(config, allowedKeys, prefix = "") {
  const allowedSet = new Set(allowedKeys);

  for (const [key, value] of Object.entries(config)) {
    const fullKey = prefix ? `${prefix}.${key}` : key;

    if (!allowedSet.has(key)) {
      const suggestion = findClosestMatch(key, allowedKeys);
      const hint = suggestion ? ` Did you mean "${suggestion}"?` : "";
      console.warn(`Unknown config key: "${fullKey}"${hint}`);
    }

    // Recurse into nested plain objects
    if (value && typeof value === "object" && !Array.isArray(value)) {
      const nestedAllowed = allowedSet.has(key) ? allowedKeys : [];
      warnUnknownKeys(value, nestedAllowed, fullKey);
    }
  }
}

function findClosestMatch(key, candidates) {
  let best = null;
  let bestScore = Infinity;

  for (const candidate of candidates) {
    const score = levenshtein(key, candidate);
    if (score < bestScore) {
      bestScore = score;
      best = candidate;
    }
  }

  // Only suggest if reasonably close
  return bestScore <= 2 ? best : null;
}

function levenshtein(a, b) {
  const dp = Array.from({ length: a.length + 1 }, (_, i) =>
    Array(b.length + 1).fill(i)
  );
  for (let j = 0; j <= b.length; j++) dp[0][j] = j;

  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
    }
  }
  return dp[a.length][b.length];
}
```

