## Robust Version (Parallel with Error Handling)

```javascript
async function sendWelcomeEmails(users, sendEmail) {
  const results = await Promise.allSettled(
    users.map(user => sendEmail(user))
  );

  const failures = results
    .map((result, i) => ({ result, user: users[i] }))
    .filter(({ result }) => result.status === 'rejected');

  if (failures.length > 0) {
    console.error(`Failed to send ${failures.length} of ${users.length} emails:`);
    for (const { result, user } of failures) {
      console.error(`  - ${user.email ?? user.id}: ${result.reason}`);
    }
  }

  return {
    sent: results.length - failures.length,
    failed: failures.length,
  };
}
```

## Rate-Limited Version (Batched)

Useful when your email provider has rate limits:

```javascript
async function sendWelcomeEmails(users, sendEmail, { batchSize = 10, delayMs = 1000 } = {}) {
  const stats = { sent: 0, failed: 0 };

  for (let i = 0; i < users.length; i += batchSize) {
    const batch = users.slice(i, i + batchSize);

    const results = await Promise.allSettled(batch.map(sendEmail));

    for (const result of results) {
      if (result.status === 'fulfilled') stats.sent++;
      else {
        stats.failed++;
        console.error('Send failed:', result.reason);
      }
    }

    // Pause between batches (skip after the last one)
    if (i + batchSize < users.length) {
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }

  return stats;
}
```

