```javascript
/**
 * Sends a welcome email to each user in the list.
 *
 * @param {Array<Object>} users - List of user objects.
 * @param {Function} sendEmail - Async function that takes a user and sends the email.
 * @param {Object} [options]
 * @param {number} [options.concurrency=5] - Max number of emails to send in parallel.
 * @returns {Promise<{sent: Array, failed: Array}>}
 */
async function sendWelcomeEmails(users, sendEmail, { concurrency = 5 } = {}) {
  const sent = [];
  const failed = [];

  // Simple concurrency-limited worker pool
  let index = 0;

  async function worker() {
    while (index < users.length) {
      const currentIndex = index++;
      const user = users[currentIndex];

      try {
        await sendEmail(user);
        sent.push(user);
      } catch (err) {
        failed.push({ user, error: err });
        console.error(`Failed to send welcome email to ${user.email}:`, err);
      }
    }
  }

  const workers = Array.from(
    { length: Math.min(concurrency, users.length) },
    () => worker()
  );

  await Promise.all(workers);

  return { sent, failed };
}
```

