/**
 * Adds products to a shopping cart.
 * @param {Map<string, {product: object, quantity: number}>} cart - The cart Map.
 * @param {Array<object>} products - Array of products to add.
 * @param {string} products[].id - Unique product identifier (used as Map key).
 * @returns {Map} The updated cart.
 */
function addToCart(cart, products) {
  for (const product of products) {
    const existing = cart.get(product.id);

    if (existing) {
      existing.quantity += 1;
    } else {
      cart.set(product.id, { product, quantity: 1 });
    }
  }
  return cart;
}
```

### Example usage

```javascript
const cart = new Map();

const items = [
  { id: 'apple', name: 'Apple', price: 0.5 },
  { id: 'banana', name: 'Banana', price: 0.3 },
  { id: 'apple', name: 'Apple', price: 0.5 },
  { id: 'cherry', name: 'Cherry', price: 2.0 },
  { id: 'banana', name: 'Banana', price: 0.3 },
  { id: 'apple', name: 'Apple', price: 0.5 },
];

addToCart(cart, items);

console.log([...cart.entries()]);
// [
