  const next = new Map(cart);
  for (const product of products) {
    const existing = next.get(product.id);
    next.set(
      product.id,
      existing
        ? { ...existing, quantity: existing.quantity + 1 }
        : { ...product, quantity: 1 }
    );
  }
  return next;
}
```

Pick the mutable version if you want the simplest, most memory-efficient code; pick the immutable version if you're working with React state or another library that relies on referential equality to detect changes.

# Adding Products to a Shopping Cart Map

Here's a clean implementation that handles duplicate products by incrementing their quantity:

```javascript
/**
 * Adds products to a shopping cart, increasing quantity if the product already exists.
 * @param {Map<string, number>} cart - The shopping cart Map (productId -> quantity)
 * @param {Array<{id: string, quantity?: number}>} products - Products to add
 * @returns {Map<string, number>} The updated cart
 */
function addToCart(cart, products) {
  for (const product of products) {
    const { id, quantity = 1 } = product;
    const currentQty = cart.get(id) ?? 0;
    cart.set(id, currentQty + quantity);
  }
  return cart;
}
```

## Usage Example

```javascript
