// { product: { id: 'b2', name: 'Notebook', price: 5.49, quantity: 2 }, quantity: 2 }
```

## Key Points

- **`cart.has(id)`** checks for an existing entry; if found, we mutate the stored object's `quantity` rather than calling `set` again (both work, but mutation is cheaper and preserves object identity).
- **`quantity = 1`** uses a default parameter so products without an explicit quantity still add one unit.
- **Using `id` as the key** ensures two entries with the same product are merged, even if the object references differ.

## Alternative: Immutable Version

If you prefer not to mutate existing entries:

```javascript
function addToCart(cart, products) {
  for (const product of products) {
    const { id, quantity = 1 } = product;
    const current = cart.get(id);
    cart.set(id, {
      product,
      quantity: (current?.quantity ?? 0) + quantity,
    });
  }
  return cart;
}
```

Assuming each product has a unique `id`, and the cart `Map` stores `id -> { ...product, quantity }`:

```js
function addProductsToCart(cart, products) {
  for (const product of products) {
    const existingItem = cart.get(product.id);

    if (existingItem) {
      existingItem.quantity += 1;
    } else {
      cart.set(product.id, { ...product, quantity: 1 });
    }
  }

  return cart;
}
```

Example usage:

```js
const cart = new Map();

addProductsToCart(cart, [
  { id: 101, name: 'Keyboard', price: 50 },
  { id: 101, name: 'Keyboard', price: 50 },
  { id: 102, name: 'Mouse', price: 25 }
]);

console.log(cart);
// Map(2) {
//   101 => { id: 101, name: 'Keyboard', price: 50, quantity: 2 },
//   102 => { id: 102, name: 'Mouse', price: 25, quantity: 1 }
// }
```

If you instead want the `Map` key to be the product object itself and the value to be the quantity, you can use:

```js
function addProductsToCart(cart, products) {
  for (const product of products) {
    cart.set(product, (cart.get(product) || 0) + 1);
  }
  return cart;
}
```

But using a unique `id` as the key is usually safer.

# Adding Products to a Shopping Cart Map

```javascript
/**
 * Adds each product in the array to the shopping cart.
 * If a product already exists, its quantity is increased.
 *
 * @param {Map<string, number>} cart - The shopping cart (product name -> quantity)
 * @param {Array<{name: string, quantity?: number}>} products - Products to add
 * @returns {Map<string, number>} The updated cart
 */
function addToCart(cart, products) {
  for (const product of products) {
    const { name, quantity = 1 } = product;
    const currentQty = cart.get(name) ?? 0;
    cart.set(name, currentQty + quantity);
  }
  return cart;
}
```

## Example Usage

```javascript
const cart = new Map();

addToCart(cart, [
  { name: 'Apple', quantity: 2 },
  { name: 'Banana' },              // defaults to quantity 1
  { name: 'Apple', quantity: 3 },  // Apple now has quantity 5
]);

console.log(cart);
// Map(2) { 'Apple' => 5, 'Banana' => 1 }
```

## How It Works

1. **Iterate** over each product in the array with `for...of`.
2. **Destructure** `name` and `quantity` from each product, defaulting `quantity` to `1` if not provided.
3. **Look up** the existing quantity in the `Map` using `cart.get(name)`. The nullish coalescing operator (`??`) returns `0` if the product isn't in the cart yet.
4. **Set** the new quantity by adding the incoming quantity to the current one. `Map.set` overwrites if the key exists and inserts if it doesn't — so a single call handles both cases.

## Alternative: Functional Style

If you prefer a more concise version:

```javascript
const addToCart = (cart, products) =>
  products.reduce((c, { name, quantity = 1 }) =>
    c.set(name, (c.get(name) ?? 0) + quantity), cart);
```

## Notes

- **Mutates the original cart** — this is intentional so the same `Map` reference stays valid across calls (useful for React state or shared references). If you need immutability, clone first: `new Map(cart)`.
- **Key type** — using product `name` as the key assumes names are unique identifiers. If your products have IDs, use `product.id` instead.

# Adding Products to a Shopping Cart Map

```javascript
/**
 * Adds each product in the array to the shopping cart Map.
 * If a product already exists, its quantity is incremented.
 *
 * @param {Map<string, {product: Object, quantity: number}>} cart
 * @param {Array<{id: string, name: string, price: number}>} products
 * @returns {Map} The updated cart
 */
function addToCart(cart, products) {
  for (const product of products) {
    const existing = cart.get(product.id);

    if (existing) {
      existing.quantity += 1;
    } else {
      cart.set(product.id, { product, quantity: 1 });
    }
  }
  return cart;
}
```

### Example Usage

```javascript
const cart = new Map();

const products = [
  { id: 'p1', name: 'Apple',  price: 0.5 },
  { id: 'p2', name: 'Banana', price: 0.3 },
  { id: 'p1', name: 'Apple',  price: 0.5 }, // duplicate
  { id: 'p3', name: 'Cherry', price: 2.0 },
  { id: 'p2', name: 'Banana', price: 0.3 }, // duplicate
  { id: 'p1', name: 'Apple',  price: 0.5 }, // duplicate
];

addToCart(cart, products);

console.log(cart);
// Map(3) {
//   'p1' => { product: { id: 'p1', name: 'Apple',  price: 0.5 }, quantity: 3 },
//   'p2' => { product: { id: 'p2', name: 'Banana', price: 0.3 }, quantity: 2 },
//   'p3' => { product: { id: 'p3', name: 'Cherry', price: 2.0 }, quantity: 1 }
// }
```

### How It Works

1. **Iterate** over the incoming `products` array.
2. **Look up** each product by its `id` in the cart `Map`.
3. **If found** — bump the existing entry's `quantity` by 1.
4. **If not found** — create a new entry with `quantity: 1`.
5. **Return** the cart for convenient chaining.

### Alternative: Immutable Version

If you prefer not to mutate the existing cart:

```javascript
function addToCart(cart, products) {
  const next = new Map(cart);
  for (const product of products) {
    const existing = next.get(product.id);
    next.set(product.id, {
      product,
      quantity: existing ? existing.quantity + 1 : 1,
    });
  }
  return next;
}
```

### Notes

- **Keying by `product.id`** (not by the object itself) is essential — two different object instances representing the same product won't match with `Map`'s reference equality.
- If your products have a `quantity` field you want to honor (e.g., adding 5 apples at once), replace `+= 1` with `+= product.quantity ?? 1`.

## Main implementation

```js
/**
 * Sends a welcome email to each user in a list.
 *
 * @param {Array<{name: string, email: string}>} users  Users to email.
 * @param {(user: object) => Promise<void>|void} sendEmail  Provided mailer.
 * @returns {Promise<Array<{user: object, status: 'sent'|'failed', error?: Error}>>}
 */
async function sendWelcomeEmails(users, sendEmail) {
  if (!Array.isArray(users)) {
    throw new TypeError('users must be an array');
  }
  if (typeof sendEmail !== 'function') {
    throw new TypeError('sendEmail must be a function');
  }

  const results = [];

  // Sequential on purpose: avoids hammering the mail provider / hitting rate limits.
  for (const user of users) {
    try {
      await sendEmail(user);
      results.push({ user, status: 'sent' });
    } catch (error) {
      // One bad address shouldn't stop the rest of the batch.
      results.push({ user, status: 'failed', error });
    }
  }

  return results;
}
```

### Usage

```js
const users = [
  { name: 'Ada',   email: 'ada@example.com' },
  { name: 'Alan',  email: 'alan@example.com' },
  { name: 'Grace', email: 'grace@example.com' },
];

// Provided by you (e.g. Nodemailer, SES, Resend, SendGrid...)
async function sendEmail(user) {
  await mailer.send({
    to: user.email,
    subject: 'Welcome!',
    text: `Hi ${user.name}, welcome aboard!`,
  });
}

const results = await sendWelcomeEmails(users, sendEmail);

const failed = results.filter((r) => r.status === 'failed');
console.log(`Sent ${results.length - failed.length}/${results.length} emails`);
failed.forEach((r) => console.error(r.user.email, r.error.message));
```

## Variants

**Parallel** — faster, but sends all requests at once (watch for rate limits):

```js
async function sendWelcomeEmailsParallel(users, sendEmail) {
  const settled = await Promise.allSettled(users.map((user) => sendEmail(user)));

  return settled.map((outcome, i) =>
    outcome.status === 'fulfilled'
      ? { user: users[i], status: 'sent' }
      : { user: users[i], status: 'failed', error: outcome.reason }
  );
}
```

**Bounded concurrency** — a good middle ground for large lists:

```js
async function sendWelcomeEmailsLimited(users, sendEmail, concurrency = 5) {
  const results = [];
  const queue = [...users];

  const worker = async () => {
    while (queue.length) {
      const user = queue.shift();
      try {
        await sendEmail(user);
        results.push({ user, status: 'sent' });
      } catch (error) {
        results.push({ user, status: 'failed', error });
      }
    }
  };

  await Promise.all(
    Array.from({ length: Math.min(concurrency, users.length) }, worker)
  );

  return results;
}
```

**Synchronous `sendEmail`** — if your mailer isn't promise-based, drop the `await`:

```js
function sendWelcomeEmailsSync(users, sendEmail) {
  return users.map((user) => {
    try {
      sendEmail(user);
      return { user, status: 'sent' };
    } catch (error) {
      return { user, status: 'failed', error };
    }
  });
}
```

## Notes

- **Don't use `forEach` with `async`** — it doesn't await, so the function returns before emails are sent and errors get swallowed.
- **Validate input** if `users` comes from outside your code (e.g. skip entries missing an `email`).
- **Retry transient failures** (network errors, 5xx) with exponential backoff; don't retry permanent ones (invalid address).
- **Idempotency** — if the function may run twice, record which users were already emailed so you don't send duplicates.

