```javascript
/**
 * Sends a welcome email to every user in the list.
 *
 * @param {Array<Object>} users      - The users to email.
 * @param {Function} sendEmail       - Async function that sends one email: sendEmail(user).
 * @param {Object} [options]
 * @param {boolean} [options.sequential = false] - If true, send one at a time (rate-limit friendly).
 * @returns {Promise<{ sent: Array, failed: Array }>}
 */
async function sendWelcomeEmails(users, sendEmail, options = {}) {
  const { sequential = false } = options;

  if (!Array.isArray(users)) {
    throw new TypeError('users must be an array');
  }
  if (typeof sendEmail !== 'function') {
    throw new TypeError('sendEmail must be a function');
  }

  const sent = [];
  const failed = [];

  const sendOne = async (user) => {
    try {
      await sendEmail(user);
      sent.push(user);
    } catch (err) {
      // Log and continue so one bad address doesn't block the rest.
      console.error(`Failed to send welcome email to ${user?.email ?? 'unknown user'}:`, err);
      failed.push({ user, error: err });
    }
  };

  if (sequential) {
    for (const user of users) {
      await sendOne(user);
    }
  } else {
    // Parallel, but each email is isolated so failures don't reject the whole batch.
    await Promise.all(users.map(sendOne));
  }

  return { sent, failed };
}
```

