 * @param {boolean} [options.ownOnly=true]  Ignore inherited properties.
 * @returns {string[]} The list of disallowed keys that were found.
 */
function warnUnknownKeys(config, allowed, options = {}) {
  const { label = 'config', ownOnly = true } = options;

  if (config == null || typeof config !== 'object') {
    console.warn(`${label}: expected an object, got ${config === null ? 'null' : typeof config}`);
    return [];
