  const allowSet = allowed instanceof Set ? allowed : new Set(allowed);
  const unknown = [];

  for (const key of Object.keys(config)) {
    if (!allowSet.has(key)) {
      unknown.push(key);
      console.warn(`${label}: unknown key "${key}" is not allowed`);
    }
  }

  return unknown;
}
```

