/**
 * Adds each product to a shopping cart Map.
 * Key:   product.id (falls back to the product object itself)
 * Value: quantity
 *
 * @param {Array} products - Products to add
 * @param {Map} [cart] - Existing cart (created if omitted)
 * @returns {Map} The updated cart
 */
function addToCart(products, cart = new Map()) {
  for (const product of products) {
    const key = product.id ?? product;
    cart.set(key, (cart.get(key) ?? 0) + 1);
  }
  return cart;
}
```

