 * Adds each product to a shopping cart Map.
 * If the product is already in the cart, its quantity is increased instead.
 *
 * @param {Array} products - Array of products. Each product needs an `id`
 *                           and may have a `quantity` (defaults to 1).
 * @param {Map} cart - Existing cart to add to. A new Map is created if omitted.
 * @returns {Map} The updated cart.
 */
function addToCart(products, cart = new Map()) {
  for (const product of products) {
    const { id, quantity = 1 } = product;
    const existing = cart.get(id);

    if (existing) {
      // Product already in the cart: bump the quantity.
      cart.set(id, { ...existing, quantity: existing.quantity + quantity });
    } else {
      // New product: add it with its starting quantity.
      cart.set(id, { ...product, quantity });
    }
  }

  return cart;
}
```

