 * @param {Map<string|number, {id: string|number, name?: string, price?: number, quantity: number}>} [cart]
 * @returns {Map} the updated cart
 */
function addToCart(products, cart = new Map()) {
  for (const product of products) {
    const existing = cart.get(product.id);

    if (existing) {
      // Already in the cart — bump the quantity
      existing.quantity += product.quantity ?? 1;
    } else {
      // New item — store a copy so we don't mutate the source array
      cart.set(product.id, { ...product, quantity: product.quantity ?? 1 });
    }
  }

  return cart;
}
```

