```js
/**
 * Adds each product to a shopping cart Map.
 * If a product is already in the cart, its quantity is incremented.
 *
 * @param {Array} products - Products to add (objects with an `id`, or plain strings)
 * @param {Map} cart - Existing cart (a new one is created if omitted)
 * @returns {Map} The updated cart
 */
function addToCart(products, cart = new Map()) {
  for (const product of products) {
    const isObject = typeof product === 'object' && product !== null;
    const key = isObject ? product.id : product;
    const details = isObject ? { ...product } : { name: product };

    const existing = cart.get(key);

    if (existing) {
      // Already in the cart → bump the quantity
      cart.set(key, { ...existing, quantity: existing.quantity + 1 });
    } else {
      // First time seen → add with quantity 1
      cart.set(key, { ...details, quantity: 1 });
    }
  }

  return cart;
}
```

