```js
/**
 * Adds each product to a shopping cart Map.
 * The Map is keyed by product id, and the value is the quantity.
 * If a product is already in the cart, its quantity is increased.
 *
 * @param {Array<{id: string|number, quantity?: number}>} products
 * @param {Map} cart Existing cart (optional) — a new one is created if omitted.
 * @returns {Map} The updated cart.
 */
function addToCart(products, cart = new Map()) {
  if (!Array.isArray(products)) {
    throw new TypeError('products must be an array');
  }

  for (const product of products) {
    if (product == null || product.id == null) {
      throw new TypeError('each product must have an id');
    }

    const currentQty = cart.get(product.id) ?? 0;
    const addQty = product.quantity ?? 1;
    cart.set(product.id, currentQty + addQty);
  }

  return cart;
}
```

